      "content": "{\n  \"name\": \"@ethanyoq/dsh-ai-novel-writer\",\n  \"version\": \"0.1.0\",\n  \"description\": \"A local-first novel project plugin for DeepSeek Harness\",\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/EthanYoQ/AI-Novel-Writer.git\",\n    \"directory\": \"plugins/dsh-ai-novel-writer\"\n  },\n  \"bugs\": {\n    \"url\": \"https://github.com/EthanYoQ/AI-Novel-Writer/issues\"\n  },\n  \"homepage\": \"https://github.com/EthanYoQ/AI-Novel-Writer/tree/master/plugins/dsh-ai-novel-writer#readme\",\n  \"publishConfig\": {\n    \"access\": \"public\"\n  },\n  \"type\": \"module\",\n  \"packageManager\": \"pnpm@11.11.0\",\n  \"main\": \"lib/index.js\",\n  \"types\": \"lib/types/index.d.ts\",\n  \"exports\": {\n    \".\": {\n      \"types\": \"./lib/types/index.d.ts\",\n      \"default\": \"./lib/index.js\"\n    },\n    \"./agent\": {\n      \"types\": \"./lib/types/agent.d.ts\",\n      \"default\": \"./lib/agent.js\"\n    },\n    \"./agent-v2\": {\n      \"types\": \"./lib/types/agent-v2.d.ts\",\n      \"default\": \"./lib/agent-v2.js\"\n    },\n    \"./client\": {\n      \"types\": \"./lib/types/client/index.d.ts\",\n      \"default\": \"./lib/client.js\"\n    },\n    \"./cordis.patch.yml\": \"./cordis.patch.yml\",\n    \"./package.json\": \"./package.json\"\n  },\n  \"files\": [\n    \"lib/index.js\",\n    \"lib/agent.js\",\n    \"lib/agent-v2.js\",\n    \"lib/client.js\",\n    \"lib/types/**/*.d.ts\",\n    \"cordis.patch.yml\",\n    \"presets/**\",\n    \"README.md\",\n    \"LICENSE\",\n    \"THIRD_PARTY_NOTICES.md\"\n  ],\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"inject\": [\n        \"@deepseek-ai/dsh-client-runtime\",\n        \"@deepseek-ai/dsh-client-connection\",\n        \"@deepseek-ai/dsh-client-ui-layout\",\n        \"@deepseek-ai/dsh-client-ui-settings-plugins\",\n        \"@deepseek-ai/dsh-client-ui-sidebar\"\n      ],\n      \"platform\":